# game/views.py
def index(request):
    return render(request, "game/index.html")

# new_puzzle is untouched:
def new_puzzle(request):
    puzzle, solution = generator.generate_puzzle()
    return JsonResponse({"puzzle": puzzle, "solution": solution})

class IndexIsShellTests(TestCase):
    def test_no_puzzle_payload_in_html(self):
        html = self.client.get(reverse("game:index")).content.decode()
        self.assertNotIn("puzzle-data", html)
        self.assertNotIn("solution-data", html)

    @patch("game.views.generator.generate_puzzle")          # EF9
    def test_index_does_not_generate(self, gen):
        self.client.get(reverse("game:index"))
        gen.assert_not_called()
